            ("2.2", ["sf-pd1", "events"], "What is the difference between Change Data Capture and Platform Events?", ["CDC publishes changes to standard/custom object records; Platform Events are custom event schemas", "They are identical", "CDC only works in sandboxes", "Platform Events cannot be subscribed to in Apex"], [0], "CDC streams record changes. Platform Events are custom-defined integration events."),
            ("2.2", ["sf-pd1", "triggers"], "Can triggers exist on Platform Event objects?", ["Yes, after-insert triggers can subscribe to event messages", "No, only Flow can handle events", "Only before-insert on events", "Only in managed packages"], [0], "Platform Event triggers run after events are published, enabling Apex subscribers."),
            ("2.2", ["sf-pd1", "flows"], "Which Flow feature replaces criteria-based Process Builder decisions?", ["Decision elements with formulas and conditions", "Only Apex actions", "Approval processes", "Workflow outbound messages only"], [0], "Flow Decision elements evaluate conditions to route automation paths declaratively."),
            ("2.2", ["sf-pd1", "invocable"], "What annotation marks an Apex method callable from Flow?", ["@InvocableMethod", "@AuraEnabled", "@RemoteAction", "@Future"], [0], "@InvocableMethod exposes static methods to Flow. @AuraEnabled is for Lightning/UI controllers."),
            ("2.2", ["sf-pd1", "invocable"], "Can an @InvocableMethod perform DML?", ["Yes, subject to governor limits like any Apex", "No, invocable methods are read-only", "Only in test context", "Only on Platform Events"], [0], "Invocable methods run as Apex with full DML/query capabilities within limits."),
            ("2.2", ["sf-pd1", "triggers"], "What is the maximum number of records Trigger.new can contain per execution?", ["200 (or 2,000 for certain Data Loader bulk loads in before triggers)", "1", "10,000", "50,000"], [0], "Standard bulk size is 200 records per trigger execution. Some bulk API loads can pass larger sets in before triggers."),
            ("2.2", ["sf-pd1", "governor-limits"], "How many Queueable jobs can be added to the queue per transaction?", ["50", "1", "100", "Unlimited"], [0], "You can enqueue up to 50 Queueable jobs from a single transaction."),
