            ("2.2", ["sf-pd1", "automation"], "A validation rule and a before trigger both set the same field. Which takes precedence for blocking a save?", ["Validation rules can still fail the save after before trigger field changes", "Triggers always override validation", "Validation rules never run if a trigger exists", "Whichever runs last always wins without errors"], [0], "Before triggers can change fields, but validation rules still evaluate and can add field errors blocking save."),
            ("2.2", ["sf-pd1", "platform-events"], "Are Platform Event triggers bulkified?", ["Yes, they can receive up to 2,000 events per trigger invocation", "No, one event per trigger", "Only when published from Flow", "Only in enterprise editions"], [0], "Event triggers process batches of published events, requiring bulk-safe handler code."),
            ("2.2", ["sf-pd1", "design"], "What is a key reason to use a trigger handler class?", ["Separate trigger events from business logic for testing and maintenance", "Eliminate the need for bulkification", "Disable governor limits", "Avoid writing test classes"], [0], "Handler classes centralize logic, improve testability, and support recursion and routing patterns."),
            ("2.2", ["sf-pd1", "async"], "Which method monitors Batch Apex job status programmatically?", ["AsyncApexJob query by Job Id from Database.executeBatch return value", "Batch.getStatus()", "System.batchStatus()", "Monitor tab API only"], [0], "Database.executeBatch returns an ID you can query in AsyncApexJob for status, items processed, and errors."),
            ("2.2", ["sf-pd1", "flows"], "What is an autolaunched flow?", ["A flow without screens that runs in the background via triggers, Apex, or REST", "A flow that always shows UI modals", "A deprecated Workflow Rule", "A Visualforce extension"], [0], "Autolaunched flows run without user interaction and can be invoked by multiple entry points."),
            ("2.2", ["sf-pd1", "triggers"], "Can you perform DML on Trigger.old records in a before delete trigger?", ["No; delete them with delete Trigger.old or delete operator on the list — you cannot update old records being deleted", "Yes, update Trigger.old freely", "Only insert new versions", "Only with merge"], [0], "In before delete, records are being removed. You can cancel delete with addError or cascade deletes, not update old into new state."),
