def format_card(card_id: int, domain: str, task: str, tags: list, question: str, options: list, correct: list, explanation: str) -> str:
    tags_str = ", ".join(f"'{t}'" for t in tags)
    options_str = ",\n      ".join(f"'{o.replace(chr(39), chr(92)+chr(39))}'" for o in options)
    correct_str = ", ".join(str(c) for c in correct)
    q = question.replace("'", "\\'")
    e = explanation.replace("'", "\\'")
    return f"""  {{
    id: 'pd1-{card_id:03d}',
    domain: '{domain}',
    task: '{task}',
    tags: [{tags_str}],
    question: '{q}',
    options: [
      {options_str},
    ],
    correctAnswers: [{correct_str}],
    explanation: '{e}',
  }}"""


DOMAIN_LIMITS = {
    "domain1-developer-fundamentals.ts": 48,
    "domain2-process-automation-logic.ts": 53,
    "domain3-user-interface.ts": 47,
    "domain4-testing-debugging-deployment.ts": 42,
}


def write_domain(domain_cfg: dict) -> int:
    limit = DOMAIN_LIMITS[domain_cfg["file"]]
    cards = domain_cfg["cards"][:limit]
    start = domain_cfg["start"]
    lines = [
        "import type { Card } from '../../../core/types'",
        "",
        f"export const {domain_cfg['export']}: Card[] = [",
    ]
    for i, card in enumerate(cards):
        card_id = start + i
        lines.append(format_card(card_id, domain_cfg["domain"], *card) + ",")
    lines.append("]")
    lines.append("")
    path = os.path.join(BASE, domain_cfg["file"])
    os.makedirs(BASE, exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))
    return len(cards)


def main():
    total = 0
    for d in DOMAINS:
        count = write_domain(d)
        print(f"Wrote {d['file']}: {count} cards")
        total += count
    print(f"Total: {total} cards")


if __name__ == "__main__":
    main()
